def unique(values):
    if values is None:
        raise TypeError("values must be a list")
    return list(dict.fromkeys(values))

def unique(values):
    if values is None:
        raise TypeError("values must be a list")
    seen = set()
    out = []
    for item in values:
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out

def unique(values):
    if values is None:
        raise TypeError("values must be a list")
    seen = set()
    out = []
    for item in values:
        try:
            key = item
        except TypeError:
            key = set()
            for k, v in item.items():
                key.update(v.items())
        if key not in seen:
            seen.add(key)
            out.append(item)
    return out
